  while (f && info.length < 15) {
    const typeName = typeof f.type === 'string' ? f.type : (f.type?.displayName || f.type?.name || 'Unknown');
    const memoKeys = f.memoizedProps ? Object.keys(f.memoizedProps) : [];
    info.push({
      typeName,
      memoKeys,
      propsSample: {
        value: f.memoizedProps?.value,
        values: f.memoizedProps?.values,
        min: f.memoizedProps?.min,
        max: f.memoizedProps?.max,
        step: f.memoizedProps?.step,
        onChange: !!f.memoizedProps?.onChange,
        onKeyDown: !!f.memoizedProps?.onKeyDown
      }
    });
    f = f.return;
  }
  return info;
});

