const tabId = 730410078;

const sliderDetails = await browserjs(tabId, () => {
  const sliders = document.querySelectorAll('span[role="slider"]');
  const minSlider = sliders[0];
  const propsKey = Object.keys(minSlider).find(k => k.startsWith('__reactProps'));
  const fiberKey = Object.keys(minSlider).find(k => k.startsWith('__reactFiber'));

  const fiber = minSlider[fiberKey];
  // Let's traverse up the fiber tree to see state/handlers
  let curr = fiber;
  const components = [];
  while (curr) {
    if (curr.type && typeof curr.type === 'function') {
      components.push(curr.type.name || 'Anonymous');
    } else if (typeof curr.type === 'string') {
      components.push(curr.type);
    }
    curr = curr.return;
  }

  return {
    components: components.slice(0, 15),
    onKeyDown: minSlider[propsKey]?.onKeyDown?.toString()
  };
});

console.log(JSON.stringify(sliderDetails, null, 2));

