const sliderStructure = await browserjs(tabId, () => {
  const container = document.querySelector('div[aria-label="Filter options"]');
  const items = Array.from(container.children);
  const playtimeItem = items.find(item => item.querySelector('button')?.innerText?.trim().startsWith('Playtime'));
  const popover = playtimeItem?.querySelector('[popover]');

  const track = popover.querySelector('.-nNjOur8lh62cpxs1Jnth') || popover.querySelector('.Ib6RCjwueJUjl7aWNipFW');
  const sliders = popover.querySelectorAll('[role="slider"]');
  const minSlider = sliders[0];

  // Look at props on track and minSlider
  const getProps = el => {
    if (!el) return null;
    const k = Object.keys(el).find(k => k.startsWith('__reactProps'));
    return k ? Object.keys(el[k]) : null;
  };

  const getFiber = el => {
    if (!el) return null;
    const k = Object.keys(el).find(k => k.startsWith('__reactFiber'));
    return el[k];
  };

  const trackPropsKey = Object.keys(track || {}).find(k => k.startsWith('__reactProps'));
  const trackFiber = getFiber(track);

  // Let's inspect memoizedProps of slider and parent
  let parentFiber = getFiber(minSlider);
  const fiberChain = [];
  while (parentFiber && fiberChain.length < 10) {
    if (parentFiber.memoizedProps) {
      fiberChain.push({
        name: parentFiber.type?.name || parentFiber.type,
        props: Object.keys(parentFiber.memoizedProps)
      });
    }
    parentFiber = parentFiber.return;
  }

  return {
    trackProps: trackPropsKey ? Object.keys(track[trackPropsKey]) : null,
    minSliderProps: getProps(minSlider),
    fiberChain
  };
});

