const tabId = 730410078;

const inspectSliderParent = await browserjs(tabId, () => {
  const container = document.querySelector('div[aria-label="Filter options"]');
  const items = Array.from(container.children);
  const playtimeItem = items.find(item => item.querySelector('button')?.innerText?.trim().startsWith('Playtime'));
  const popover = playtimeItem?.querySelector('[popover]');
  const minSlider = popover.querySelector('[role="slider"]');

  const getFiber = el => {
    const k = Object.keys(el || {}).find(k => k.startsWith('__reactFiber'));
    return k ? el[k] : null;
  };

  let f = getFiber(minSlider);
  let dNode = null;
  while (f) {
    if (f.memoizedProps?.onValueSettled) {
      dNode = f;
      break;
    }
    f = f.return;
  }

  // Let's see dNode's return (parent)
  let parent = dNode?.return;
  const parentDetails = [];
  while (parent && parentDetails.length < 10) {
    parentDetails.push({
      typeName: parent.type?.name || (typeof parent.type === 'string' ? parent.type : 'Func/Obj'),
      memoState: parent.memoizedState ? Object.keys(parent.memoizedState) : null,
      memoProps: parent.memoizedProps ? Object.keys(parent.memoizedProps) : null
    });
    // Check if any state contains hours or numbers
    if (parent.memoizedState) {
      let s = parent.memoizedState;
      let depth = 0;
      while (s && depth < 10) {
        parentDetails[parentDetails.length - 1][`state_${depth}`] = typeof s.memoizedState === 'object' ? JSON.stringify(s.memoizedState) : s.memoizedState;
        s = s.next;
        depth++;
      }
    }
    parent = parent.return;
  }

  return {
    dNodeProps: {
      onValueChange: dNode?.memoizedProps?.onValueChange?.toString(),
      onValueSettled: dNode?.memoizedProps?.onValueSettled?.toString(),
    },
    parentDetails
  };
});

console.log("Slider Parent inspection:\n", JSON.stringify(inspectSliderParent, null, 2));

