  const allRadio = document.querySelector('input[name="review_language"][value="all"]');
  if (allRadio) {
    allRadio.parentElement.click();
    return { clickedRadio: true, checked: allRadio.checked };
  }
  return { clickedRadio: false };
});
console.log("Selected All Languages:", selectAllLang);

await new Promise(r => setTimeout(r, 2000));

